<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { apiRequest } from './api'
type Backup={id:string;name:string;created_at:string;agent_count:number}
type Job={job_id:string;status:string;percent:number;phase:string;error?:string}
const backups=ref<Backup[]>([]),error=ref(''),loading=ref(false),creating=ref(false),progress=ref<Job|null>(null),fileInput=ref<HTMLInputElement|null>(null)
async function refresh(){loading.value=true;try{backups.value=await apiRequest<Backup[]>('/backups');error.value=''}catch(cause){error.value=cause instanceof Error?cause.message:'Could not load backups.'}finally{loading.value=false}}
async function waitForJob(id:string){for(;;){const job=await apiRequest<Job>(`/backups/jobs/${encodeURIComponent(id)}`);progress.value=job;if(job.status==='completed')return;if(job.status==='failed'||job.status==='cancelled')throw new Error(job.error||'Backup did not complete.');await new Promise(resolve=>window.setTimeout(resolve,350))}}
async function create(){creating.value=true;error.value='';progress.value=null;try{const job=await apiRequest<Job>('/backups/jobs',{method:'POST',body:JSON.stringify({name:`Workspace backup ${new Date().toLocaleString()}`,scope:{include_agents:true,include_global_config:true,include_secrets:false,include_skill_pool:true}})});await waitForJob(job.job_id);await refresh()}catch(cause){error.value=cause instanceof Error?cause.message:'Could not create backup.'}finally{creating.value=false}}
async function restore(id:string){if(!window.confirm('Restore this backup into the current workspace?'))return;try{await apiRequest(`/backups/${encodeURIComponent(id)}/restore`,{method:'POST',body:JSON.stringify({include_agents:true,include_global_config:true,include_secrets:false,include_skill_pool:true,mode:'custom'})})}catch(cause){error.value=cause instanceof Error?cause.message:'Could not restore backup.'}}
async function remove(id:string){try{await apiRequest('/backups/delete',{method:'POST',body:JSON.stringify({ids:[id]})});await refresh()}catch(cause){error.value=cause instanceof Error?cause.message:'Could not delete backup.'}}
async function importArchive(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const form=new FormData();form.append('file',file);try{await apiRequest('/backups/import',{method:'POST',body:form});await refresh()}catch(cause){error.value=cause instanceof Error?cause.message:'Could not import backup.'}finally{if(fileInput.value)fileInput.value.value=''}}
onMounted(()=>void refresh())
</script>
<template><section class="settings-page"><header class="settings-heading"><div><p class="eyebrow">DATA</p><h1>Backups</h1></div><span><input ref="fileInput" type="file" accept=".zip,application/zip" hidden @change="importArchive"><button :disabled="creating" @click="fileInput?.click()">Import</button><button :disabled="creating" @click="create">{{ creating?'Creating…':'Create backup' }}</button></span></header><p v-if="progress" class="settings-card">{{ progress.phase }} · {{ progress.percent }}%</p><p v-if="error" class="inline-error">{{ error }}</p><div class="settings-card"><p v-if="loading">Loading backups…</p><p v-else-if="!backups.length">No backups yet.</p><div v-for="backup in backups" :key="backup.id" class="skills-item"><span><strong>{{ backup.name||backup.id }}</strong><small>{{ backup.created_at }} · {{ backup.agent_count }} agents</small></span><span><a :href="`/api/backups/${encodeURIComponent(backup.id)}/export`">Export</a><button @click="restore(backup.id)">Restore</button><button @click="remove(backup.id)">Delete</button></span></div></div></section></template>
